select coalesce(array_agg(distinct "category"), '{}'), coalesce(array_agg(distinct "size") filter (where "size" is not null), '{}'), coalesce(array_agg(distinct "type") filter (where "type" is not null), '{}'), coalesce(array_agg(distinct "warmth") filter (where "warmth" is not null), '{}'), coalesce(array_agg(distinct "formality") filter (where "formality" is not null), '{}'), coalesce(array_agg(distinct "care_wash") filter (where "care_wash" is not null), '{}'), (
        select coalesce(array_agg(distinct worn.material), '{}')
        from garment owned cross join lateral unnest(owned.materials) as worn(material)
        where owned.owner_id = $1 and owned.status <> 'wishlist'
      ) from "garment" where ("garment"."owner_id" = $2 and "garment"."status" <> $3)
